export function pageRows(rows,size=10,page=1){if(![10,25,50].includes(size))throw Error('Invalid page size.');const pages=Math.max(1,Math.ceil(rows.length/size));const current=Math.max(1,Math.min(pages,Math.trunc(page)||1));const start=(current-1)*size;return {items:rows.slice(start,start+size),page:current,pages,total:rows.length,start:rows.length?start+1:0,end:Math.min(start+size,rows.length)};}
export function personLabel(person,mode='full'){if(!person)return '';const full=person.name||person.id||'',short=(person.shortName||'').trim();if(mode==='short')return short||full;if(mode==='combined')return short&&short!==full?`${short} · ${full}`:full;return full;}
export async function importRows(rows,save,onProgress=()=>{},start=0){let completed=start;onProgress({completed,total:rows.length,state:'saving'});for(let i=start;i<rows.length;i++){try{await save(rows[i],i);completed=i+1;onProgress({completed,total:rows.length,state:'saving'});}catch(error){error.completed=completed;onProgress({completed,total:rows.length,state:'failed',error:error.message});throw error;}}onProgress({completed,total:rows.length,state:'complete'});return completed;}
